// PROBLEMATIQUE : la session vit dans la memoire de CETTE instance.
// Une autre instance ne verra jamais ce panier.
const paniers = {}; // objet en memoire locale

app.post("/panier/ajouter", (req, res) => {
  const user = req.userId;
  paniers[user] = paniers[user] || [];
  paniers[user].push(req.body.article);
  res.json({ ok: true });
});

// SANS ETAT : le panier est range dans un store partage (Redis),
// accessible de facon identique par toutes les instances.
import { redis } from "./redis.js";

app.post("/panier/ajouter", async (req, res) => {
  const user = req.userId;
  // on ajoute l'article a la liste stockee dans Redis sous une cle par utilisateur
  await redis.rpush(`panier:${user}`, req.body.article);
  res.json({ ok: true });
});
